Write a pytest test for a cache decorator that mocks the underlying function and verifies it is called only once for repeated identical arguments.

import functools

def cached_call(fn):
    store = {}
    @functools.wraps(fn)
    def wrapper(*args):
        if args not in store:
            store[args] = fn(*args)
        return store[args]
    return wrapper

